import{_ as t,o,c as a,a6 as i}from"./chunks/framework.CCKCzdWs.js";const p=JSON.parse('{"title":"Codex CLI","description":"Use a local Codex ChatGPT login for Piwi diagnosis and the assistant, with isolated execution, structured output and scoped read-only tools.","frontmatter":{"title":"Codex CLI","description":"Use a local Codex ChatGPT login for Piwi diagnosis and the assistant, with isolated execution, structured output and scoped read-only tools.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/codex-cli.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/codex-cli.html"}],["meta",{"property":"og:title","content":"Codex CLI | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Use a local Codex ChatGPT login for Piwi diagnosis and the assistant, with isolated execution, structured output and scoped read-only tools."}]]},"headers":[],"relativePath":"guide/codex-cli.md","filePath":"guide/codex-cli.md","lastUpdated":1793032704000}'),s={name:"guide/codex-cli.md"};function n(r,e,d,l,c,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="codex-cli" tabindex="-1">Codex CLI <a class="header-anchor" href="#codex-cli" aria-label="Permalink to &quot;Codex CLI&quot;">​</a></h1><p>Piwi can use <a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">Codex CLI</a> for diagnosis, research and the assistant without an OpenAI API key. The CLI must be installed on the machine running Piwi.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Install Codex CLI and run <code>codex login</code> with your ChatGPT account.</li><li>Choose <strong>Codex (local)</strong> in <strong>Settings → AI</strong>. The desktop app finds <code>codex</code> on PATH; a self-hosted server enables it with <code>PIWI_CODEX_CLI_PATH</code> pointing to the executable&#39;s absolute path. Alternatively, set <code>PIWI_AI_PROVIDER=codex-cli</code> for environment-managed settings.</li><li>Use <strong>Recheck</strong> in the status card to check availability, version and authentication. Sign-in and sign-out stay in Codex. No API key or Piwi secret-encryption key is needed for this provider.</li></ol><p>Piwi reuses the file-backed login at <code>CODEX_HOME/auth.json</code> (default: <code>.codex/auth.json</code> in your home directory). For a keyring-only login, set <code>cli_auth_credentials_store = &quot;file&quot;</code> in your Codex configuration and run <code>codex login</code>. Use a recent CLI with the isolation flags; Piwi refuses incompatible versions.</p><h2 id="models-and-output" tabindex="-1">Models and output <a class="header-anchor" href="#models-and-output" aria-label="Permalink to &quot;Models and output&quot;">​</a></h2><p>Diagnosis, research and assistant roles accept a model ID; blank uses <code>gpt-5.4</code>. Embeddings need an OpenAI-compatible provider. Codex receives JSON Schema through its structured-output option. Its JSONL events stream completed messages, so text can arrive in message-sized chunks. Input-token counts already include cached input tokens; the cached count is also reported separately. Codex does not report a dollar cost, so Piwi leaves it unknown. Image attachments are omitted for CLI diagnosis; text evidence is still sent.</p><h2 id="isolation" tabindex="-1">Isolation <a class="header-anchor" href="#isolation" aria-label="Permalink to &quot;Isolation&quot;">​</a></h2><p>Each invocation uses a private temporary home and working directory with only a login snapshot. Refreshed credentials are saved back if the source login is unchanged. User configuration, project instructions, skills, hooks, plugins and unrelated credentials are excluded. Built-in execution, filesystem and web tools are disabled. The assistant receives only its turn&#39;s MCP endpoint, with its short-lived token and allowed tools; calls retain the asking user&#39;s project scope, read-only access and answer limits. Temporary files are removed when the process exits or times out.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/ai-provider.html">AI provider</a></li><li><a href="/features/assistant.html">Assistant</a></li><li><a href="/reference/configuration.html#ai-diagnosis">Configuration reference</a></li></ul>',11)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
